function [sun] = fast_start_sun(jd0_utc)
%FAST_START_SUN  The Sun (env's fast series) at the TT date of the UTC epoch jd0_utc, where the fast orbit starts.
%   jd0_utc: real[1] (passed a plain number)
%   returns sun: real[m][3] (passed in m)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    sun = zeros(3, 1);
    sun = asils.models.sunfast.sun_position_fast((jd0_utc + (69.184 / 86400)));
end
